import { retentionMs } from './policy.mjs';

// Identity is the pair (tenantId, key). Both may contain arbitrary punctuation,
// so build a collision-free composite key instead of joining with a delimiter:
// length-prefix each part so the encoding is injective and unambiguous.
function identityOf(tenantId, key) {
  const tenant = String(tenantId);
  const k = String(key);
  return `${tenant.length}:${tenant}|${k.length}:${k}`;
}

function isExpired(entry, now) {
  return now >= entry.savedAt + retentionMs;
}

export function createStore() {
  const entries = new Map();

  return {
    lookup({ tenantId, key, fingerprint, now }) {
      const identity = identityOf(tenantId, key);
      const entry = entries.get(identity);
      if (entry === undefined) return { kind: 'miss' };
      if (isExpired(entry, now)) {
        // An expired entry behaves as a miss, even when the fingerprint differs.
        entries.delete(identity);
        return { kind: 'miss' };
      }
      if (entry.fingerprint === fingerprint) {
        return { kind: 'hit', response: entry.response };
      }
      return { kind: 'conflict' };
    },

    save({ tenantId, key, fingerprint, response, now }) {
      const identity = identityOf(tenantId, key);
      entries.set(identity, { fingerprint, response, savedAt: now });
    },

    remove({ tenantId, key }) {
      const identity = identityOf(tenantId, key);
      return entries.delete(identity);
    },

    prune(now) {
      let removed = 0;
      for (const [identity, entry] of entries) {
        if (isExpired(entry, now)) {
          entries.delete(identity);
          removed += 1;
        }
      }
      return removed;
    },
  };
}

