import { retryDelay } from './policy.mjs';

const CONFLICT_RESPONSE = { status: 409, body: { error: 'idempotency_conflict' } };
const HEADER_NAME = 'Idempotency-Key';

function isSuccess(response) {
  return response.status >= 200 && response.status < 300;
}

export async function importInvoice(request, deps) {
  const { tenantId, key, fingerprint, payload, forceRefresh = false } = request;
  const { store, now, send, wait } = deps;

  const existing = store.lookup({ tenantId, key, fingerprint, now: now() });

  // A conflict is returned without sending, even for a forced refresh.
  if (existing.kind === 'conflict') return CONFLICT_RESPONSE;

  // A matching cached response replays as-is unless a refresh was requested.
  if (existing.kind === 'hit' && !forceRefresh) return existing.response;

  let attempt = 1;
  for (;;) {
    const response = await send({
      headers: { [HEADER_NAME]: key },
      body: payload,
    });

    if (isSuccess(response)) {
      // A successful refresh replaces the cached response; retention restarts
      // from this save time.
      store.save({ tenantId, key, fingerprint, response, now: now() });
      return response;
    }

    // retryDelay applies the retryable-status and attempt-cap checks first, so a
    // retryAfterMs hint can never make a permanent status retryable or allow an
    // extra attempt.
    const delay = retryDelay(response.status, attempt, response.retryAfterMs);
    if (delay === null) return response;

    await wait(delay);
    attempt += 1;
  }
}

export async function importBatch(requests, deps, options = {}) {
  const { stopOnHttpFailure = false, signal } = options;
  const responses = [];
  for (const request of requests) {
    // Cancellation is checked between items, before each item starts (including
    // the first); an in-flight import is never interrupted.
    if (signal !== undefined && signal !== null && signal.aborted) {
      throw new Error('Batch aborted');
    }
    // Sequential: each item is fully processed before the next one starts.
    // A thrown transport exception propagates and stops the batch.
    const response = await importInvoice(request, deps);
    responses.push(response);
    if (stopOnHttpFailure && !isSuccess(response)) break;
  }
  return responses;
}

