import { retentionMs } from './policy.mjs';

// Identity is the pair (tenantId, key). Neither component may be assumed free
// of punctuation, so the components are nested rather than joined by a
// delimiter: outer map keyed by tenantId, inner map keyed by key.
export function createStore() {
  const tenants = new Map();

  function bucket(tenantId, create) {
    let byKey = tenants.get(tenantId);
    if (!byKey && create) {
      byKey = new Map();
      tenants.set(tenantId, byKey);
    }
    return byKey;
  }

  function isExpired(entry, now) {
    return now >= entry.savedAt + retentionMs;
  }

  return {
    lookup({ tenantId, key, fingerprint, now }) {
      const byKey = bucket(tenantId, false);
      if (!byKey) return { kind: 'miss' };
      const entry = byKey.get(key);
      if (!entry) return { kind: 'miss' };
      if (isExpired(entry, now)) {
        byKey.delete(key);
        return { kind: 'miss' };
      }
      if (entry.fingerprint !== fingerprint) return { kind: 'conflict' };
      return { kind: 'hit', response: entry.response };
    },

    save({ tenantId, key, fingerprint, response, now }) {
      bucket(tenantId, true).set(key, {
        fingerprint,
        response,
        savedAt: now,
      });
    },

    // Removes exactly this (tenantId, key) entry. Returns true only when an
    // entry was physically present, false otherwise (including expiry-unknown
    // or absent entries). Other tenants' entries are never touched.
    remove({ tenantId, key }) {
      const byKey = bucket(tenantId, false);
      if (!byKey) return false;
      return byKey.delete(key);
    },

    // Physically removes every expired entry across all tenants, using the
    // same exact boundary as lookup: expired when now >= savedAt + retentionMs.
    // Live entries are preserved. Returns the number removed by this call, so
    // a repeat call at the same time returns zero.
    prune(now) {
      let removed = 0;
      for (const [tenantId, byKey] of tenants) {
        for (const [key, entry] of byKey) {
          if (isExpired(entry, now)) {
            byKey.delete(key);
            removed++;
          }
        }
        // Drop empty tenant buckets; identity lookups still behave as misses.
        if (byKey.size === 0) tenants.delete(tenantId);
      }
      return removed;
    },
  };
