const RETRYABLE_STATUSES = new Set([429, 502, 503, 504]);
const MAX_ATTEMPTS = 3;
const DELAYS_BY_ATTEMPT = new Map([
  [2, 250],
  [3, 500],
]);

/** Largest server hint we are willing to honor, in milliseconds. */
const MAX_RETRY_AFTER_MS = 60000;

/**
 * A server-provided retry hint is usable only when it is a finite number in the
 * inclusive range 0..60000. Zero is valid (retry immediately). Anything else
 * (non-number, NaN, Infinity, negative, above the cap) is ignored so the
 * original schedule applies.
 */
function usableRetryAfterMs(retryAfterMs) {
  return (
    typeof retryAfterMs === 'number' &&
    Number.isFinite(retryAfterMs) &&
    retryAfterMs >= 0 &&
    retryAfterMs <= MAX_RETRY_AFTER_MS
  );
