import { retentionMs } from './policy.mjs';

/**
 * Build a collision-free lookup key for the identity pair (tenantId, key).
 * Tenant IDs and keys may contain any punctuation, so a bare joined string
 * would be ambiguous (e.g. ("a:b", "c") vs ("a", "b:c")). We therefore
 * length-prefix each component; the encoding is unambiguous.
 */
function identityFor(tenantId, key) {
  const t = String(tenantId);
  const k = String(key);
  return `${t.length}:${t}${k.length}:${k}`;
}

/** An entry is expired exactly when now >= savedAt + retentionMs. */
function isExpired(entry, now) {
  return now >= entry.savedAt + retentionMs;
}

export function createStore() {
  const entries = new Map();

  return {
    lookup({ tenantId, key, fingerprint, now }) {
      const identity = identityFor(tenantId, key);
      const entry = entries.get(identity);
      if (entry === undefined) return { kind: 'miss' };

      if (isExpired(entry, now)) {
        entries.delete(identity);
        return { kind: 'miss' };
      }

      if (entry.fingerprint === fingerprint) {
        return { kind: 'hit', response: entry.response };
      }
      return { kind: 'conflict' };
    },

    save({ tenantId, key, fingerprint, response, now }) {
      const identity = identityFor(tenantId, key);
      entries.set(identity, { fingerprint, response, savedAt: now });
    },

