     * Remove exactly the (tenantId, key) entry, whether or not it has expired.
     * The identity pair is encoded, so a matching key belonging to a different
     * tenant is not affected.
     *
     * @returns {boolean} true if an entry was physically present, else false.
     */
    remove({ tenantId, key }) {
      const identity = identityFor(tenantId, key);
      return entries.delete(identity);
    },

    /**
     * Remove every expired entry across all tenants and report how many were
     * physically removed by this call. Live entries are preserved, and because
     * removal is physical, repeating prune at the same `now` removes nothing
     * more and returns 0.
     *
     * @param {number} now Current injected time in milliseconds.
     * @returns {number} Count of entries removed by this call.
     */
    prune(now) {
      let removed = 0;
      for (const [identity, entry] of entries) {
        if (isExpired(entry, now)) {
          entries.delete(identity);
          removed += 1;
        }
      }
      return removed;
    },
  };
