export const retentionMs = 48 * 60 * 60 * 1000;

// Statuses eligible for a retry. Notably 500 is NOT retryable.
const RETRYABLE_STATUSES = new Set([429, 502, 503, 504]);

// At most three attempts TOTAL (the first plus two retries).
// attempt is one-based: it is the attempt that just failed. The returned
// value is the delay in ms to wait before the next attempt.
//   attempt 1 failed -> wait 250 ms before attempt 2
//   attempt 2 failed -> wait 500 ms before attempt 3
//   attempt 3 (last) -> null, no further attempt
const MAX_ATTEMPTS = 3;
const RETRY_DELAYS_MS = [250, 500];

// Bounds for a server-supplied hint. 0 is valid (retry immediately).
const MAX_RETRY_AFTER_MS = 60000;

function hintDelay(retryAfterMs) {
  if (typeof retryAfterMs !== 'number') return null;
  if (!Number.isFinite(retryAfterMs)) return null;
  if (retryAfterMs < 0 || retryAfterMs > MAX_RETRY_AFTER_MS) return null;
  return retryAfterMs;
}

export function retryDelay(status, attempt, retryAfterMs) {
  // A non-retryable status can never be made retryable by a hint, and the
  // attempt cap is decided first so a hint can never add an extra attempt.
  if (!RETRYABLE_STATUSES.has(status)) return null;
  if (!Number.isInteger(attempt) || attempt < 1) return null;
  const retryIndex = attempt - 1;
  if (retryIndex >= MAX_ATTEMPTS - 1) return null;
  if (retryIndex >= RETRY_DELAYS_MS.length) return null;

  // Only now that another attempt is confirmed allowed may a well-formed
  // hint replace the default schedule. An unusable hint falls back to it.
  const hint = hintDelay(retryAfterMs);
  if (hint !== null) return hint;

  return RETRY_DELAYS_MS[retryIndex];
