/**
 * Build a key for the (tenantId, key) pair that cannot collide across pairs,
 * even when tenant IDs or keys contain arbitrary punctuation (including any
 * delimiter we might otherwise choose). Length-prefixing makes the encoding
 * unambiguous rather than relying on an unescaped separator.
 */
function identityKey(tenantId, key) {
  const tenant = String(tenantId);
  const token = String(key);
  return `${tenant.length}:${tenant}|${token.length}:${token}`;
}

export function createStore() {
  // identity key -> { fingerprint, response, savedAt }
  const entries = new Map();

  function isExpired(entry, now) {
    // Expire exactly when now >= savedAt + retentionMs.
    return now >= entry.savedAt + retentionMs;
  }

  function readEntry(tenantId, key, now) {
    const id = identityKey(tenantId, key);
    const entry = entries.get(id);
    if (entry === undefined) return undefined;
    if (isExpired(entry, now)) {
      entries.delete(id);
      return undefined;
    }
    return entry;
  }

  return {
    lookup({ tenantId, key, fingerprint, now }) {
      const entry = readEntry(tenantId, key, now);
      // Expired entries (and absent ones) behave as a miss, even if the
      // new fingerprint differs from the stored one.
      if (entry === undefined) return { kind: 'miss' };
      if (entry.fingerprint !== fingerprint) return { kind: 'conflict' };
      return { kind: 'hit', response: entry.response };
    },

    save({ tenantId, key, fingerprint, response, now }) {
      entries.set(identityKey(tenantId, key), {
        fingerprint,
        response,
        savedAt: now,
      });
    },

    // Remove exactly this (tenantId, key) entry. Returns true only when an
    // entry was physically present, even if it is already expired.
    remove({ tenantId, key }) {
      return entries.delete(identityKey(tenantId, key));
    },

    // Physically drop every expired entry across all tenants and report how
    // many this call removed. Live entries stay. Re-running at the same time
    // removes nothing further, so it returns zero.
    prune(now) {
      let removed = 0;
      for (const [id, entry] of entries) {
        if (isExpired(entry, now)) {
          entries.delete(id);
          removed += 1;
        }
      }
      return removed;
    },
  };
}

