import { retryDelay } from './policy.mjs';

const CONFLICT_RESPONSE = { status: 409, body: { error: 'idempotency_conflict' } };

function isSuccess(status) {
  return status >= 200 && status <= 299;
}

export async function importInvoice(request, deps) {
  const { tenantId, key, fingerprint, payload, forceRefresh = false } = request;
  const { store, now, send, wait } = deps;

  // Lookup always runs first: a conflicting unexpired fingerprint is still a
  // conflict, whether or not a refresh was requested, and never sends.
  const existing = store.lookup({ tenantId, key, fingerprint, now: now() });
  if (existing.kind === 'conflict') return { ...CONFLICT_RESPONSE };

  if (existing.kind === 'hit' && !forceRefresh) {
    // Ordinary replay of the stored success without sending.
    return existing.response;
  }

  const headers = { 'Idempotency-Key': key };

  for (let attempt = 1; ; attempt += 1) {
    // A transport exception must propagate: no retry, no cache entry, and any
    // still-valid cached response is untouched so a later replay still works.
    const response = await send({ headers, body: payload });

    if (isSuccess(response.status)) {
      // Only HTTP 2xx responses may be cached. Saving also restarts retention
      // from this save time, replacing any refreshed-away entry.
      store.save({ tenantId, key, fingerprint, response, now: now() });
      return response;
    }

    // Non-2xx: leave the old cached entry (if any) in place for replay, and
    // let the agreed retry policy decide whether to try again. The response
    // may carry a retryAfterMs hint, which the policy validates.
    const delay = retryDelay(response.status, attempt, response.retryAfterMs);
    if (delay === null) return response;

    await wait(delay);
  }
}

export async function importBatch(requests, deps, options = {}) {
  const { stopOnHttpFailure = false, signal } = options;
  const responses = [];

  // An empty batch returns [] even when the signal is already aborted, because
  // the abort check only happens before starting an item.
  for (const request of requests) {
    // Cancellation is checked only between items, including before the first,
    // so an in-flight import is never interrupted.
    if (signal && signal.aborted) throw new Error('Batch aborted');

    // A thrown transport exception is not caught, so it stops the batch and
    // propagates regardless of stopOnHttpFailure.
    const response = await importInvoice(request, deps);
    responses.push(response);

    // Optionally halt after recording the first non-2xx response, before the
    // next item is processed. Default behavior continues instead.
    if (stopOnHttpFailure && !isSuccess(response.status)) break;
  }

  return responses;
}
